/* ============================================================
   VOYA TAXI - COUNTRY BOUNDARY REFERENCE DATA
   Source: geoBoundaries, CC BY 4.0
   Countries: Netherlands (NLD ADM0), Belgium (BEL ADM0)
   Preserves the original geometries using PostGIS EWKB.
   Run after schema creation. Import into development first.
============================================================ */
BEGIN;
INSERT INTO public.country_boundaries
    (country_code, country_name, boundary, source_name, source_license, source_reference)
VALUES
    ('BE', 'Belgium',
     extensions.ST_GeomFromEWKB(decode('', 'hex')),
     'geoBoundaries', 'CC BY 4.0', 'BEL ADM0')
ON CONFLICT (country_code) DO UPDATE SET
    country_name = EXCLUDED.country_name,
    boundary = EXCLUDED.boundary,
    source_name = EXCLUDED.source_name,
    source_license = EXCLUDED.source_license,
    source_reference = EXCLUDED.source_reference;
INSERT INTO public.country_boundaries
    (country_code, country_name, boundary, source_name, source_license, source_reference)
VALUES
    ('NL', 'Netherlands',
     extensions.ST_GeomFromEWKB(decode('', 'hex')),
     'geoBoundaries', 'CC BY 4.0', 'NLD ADM0')
ON CONFLICT (country_code) DO UPDATE SET
    country_name = EXCLUDED.country_name,
    boundary = EXCLUDED.boundary,
    source_name = EXCLUDED.source_name,
    source_license = EXCLUDED.source_license,
    source_reference = EXCLUDED.source_reference;
COMMIT;